/**
 * Paginação de listas em memória.
 *
 * As páginas são numeradas a partir de 1. Uma lista vazia tem exatamente uma
 * página (vazia). Pedir uma página além da última devolve `items: []`, mas os
 * metadados (total, totalPages, hasPrev, hasNext) continuam válidos.
 */

function assertPositiveInt(name, value) {
  if (!Number.isInteger(value) || value < 1) {
    throw new RangeError(`${name} must be a positive integer, got ${value}`);
  }
}

/**
 * Número total de páginas para `total` itens com `pageSize` itens por página.
 * Nunca retorna menos que 1.
 */
export function countPages(total, pageSize) {
  assertPositiveInt('pageSize', pageSize);
  return Math.max(1, Math.ceil(total / pageSize));
}

/**
 * Página (1-based) em que o item de índice `index` (0-based) aparece.
 */
export function pageForIndex(index, pageSize) {
  assertPositiveInt('pageSize', pageSize);
  if (!Number.isInteger(index) || index < 0) throw new RangeError('index must be a non-negative integer');
  return Math.floor(index / pageSize) + 1;
}

/**
 * paginate(items, page = 1, pageSize = 10)
 * -> { items, page, pageSize, total, totalPages, hasPrev, hasNext }
 * Não modifica `items`.
 */
export function paginate(items, page = 1, pageSize = 10) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  assertPositiveInt('page', page);
  assertPositiveInt('pageSize', pageSize);
  const total = items.length;
  const totalPages = countPages(total, pageSize);
  const start = (page - 1) * pageSize;
  const pageItems = page <= totalPages ? items.slice(start, start + pageSize) : [];
  return {
    items: pageItems,
    page,
    pageSize,
    total,
    totalPages,
    hasPrev: page > 1,
    hasNext: page < totalPages,
  };
}

